-- LLM-drafted translations (needs_review = TRUE throughout) of Level 5's
-- lesson content (seeded by migration 0036), into the 7 non-English
-- locales — same posture as migrations 0021, 0038-0040.
INSERT INTO lesson_translations (lesson_id, locale, title, content) VALUES
    ('00000000-0000-0000-0000-000000004101', 'pcm', 'Wetin Resilience Really Mean', 'People dey often misunderstand resilience as "to no dey affected" by hard matter, or "to bounce back" as if nothing happen. Better picture be say resilience na capacity to dey affected by hard experience and still find way forward -- e dey include the struggle, e no mean say there no be struggle at all.\n\nResilience no be fixed personal character wey some people get and others no get. Dem dey build am through mixture of factors: relationship wey dey support you, practical coping skills, sense of meaning, and sometimes, practice to recover from smaller setback before you go face bigger one.\n\nTo frame resilience like dis matter well-well because e mean say you fit develop am. To struggle with something hard no be proof say you no get resilience -- e fit be the process wey resilience dey show as dem dey build am.'),
    ('00000000-0000-0000-0000-000000004101', 'yo', 'Ohun Tí Ìfaradà Ní Ìtumọ̀ Gidi Rẹ̀', 'Ènìyàn sábà máa ń ṣìyèméjì ìfaradà gẹ́gẹ́ bí "àìní ipa" láti ara ohun tó le, tàbí "yíyára padà" bí ẹni pé kò sí ohun tó ṣẹlẹ̀. Àwòrán tí ó bá ọ̀rọ̀ mu jùlọ ni pé ìfaradà jẹ́ agbára láti ní ipa látinú ìrírí tí ó le tí ó sì síbẹ̀ rí ọ̀nà síwájú -- ó ní ìjàkadì nínú, kì í ṣe àìsí ìjàkadì.\n\nÌfaradà kì í ṣe ànímọ́ ẹnìkọ̀ọ̀kan tí a dá sílẹ̀ tí àwọn kan ní tí àwọn mìíràn kò ní. A kọ́ ọ nípasẹ̀ àkópọ̀ àwọn ohun kan: àjọṣe tí ó ń ṣe àtìlẹ́yìn, ọgbọ́n ìbámu tí ó wúlò, ìmọ̀lára ìtumọ̀, àti nígbà mìíràn, àṣàrò àtúnbọ̀sípò látinú àwọn ìṣubú kéékèèké kí ó tó dojúkọ àwọn ńlá.\n\nṢíṣe àwòrán ìfaradà báyìí ṣe pàtàkì nítorí ó túmọ̀ sí pé a lè kọ́ ọ. Ìjàkadì pẹ̀lú ohun tí ó le kì í ṣe ẹ̀rí pé o kò ní ìfaradà -- ó lè jẹ́ ìlànà tí ìfaradà gan-an ń rí bí nígbà tí a bá ń kọ́ ọ.'),
    ('00000000-0000-0000-0000-000000004101', 'ha', 'Ma''anar Juriya Ta Ainihi', 'Mutane galibi suna kuskuren fahimtar juriya a matsayin "rashin fama" da abubuwa masu wuya, ko "dawowa cikin sauri" kamar babu abin da ya faru. Hoto mafi daidai shi ne cewa juriya ita ce karfin da za a fama da wata gogewa mai wuya sannan a sami hanya ta ci gaba -- ya hada da kokawar, ba rashin kokawar ba.\n\nJuriya kuma ba hali ne tsayayye da wasu mutane suke da shi wasu kuma ba su da shi ba. Ana ginawa ta hanyar hadewar dalilai: dangantaka masu goyan baya, basirar jurewa ta amfani, jin ma''ana, kuma sau da yawa, atisaye na farfadowa daga kananan koma-baya kafin fuskantar manyan.\n\nTsara juriya ta wannan hanya yana da muhimmanci domin yana nufin za a iya ginawa shi. Fuskantar wahala da wani abu mai wuya ba shaida ba ce cewa ba ka da juriya -- zai iya zama tsarin da juriya take dauka a lokacin da ake ginata.'),
    ('00000000-0000-0000-0000-000000004101', 'ig', 'Ihe Ntachi Obi Pụtara N''ezie', 'Ndị mmadụ na-aghọtahịekarị ntachi obi dị ka "enweghị mmetụta" site n''ihe ndị siri ike, ma ọ bụ "ịlaghachi ngwa ngwa" ka à ga-asị na ọ dịghị ihe mere. Onyonyo kwesịrị ekwesị karịa bụ na ntachi obi bụ ikike inwe mmetụta site n''ahụmịhe siri ike ma chọta ụzọ ịga n''ihu -- ọ gụnyere mgbagwoju ahụ, ọ bụghị enweghị mgbagwoju.\n\nNtachi obi abụghịkwa àgwà onwe mmadụ a kpachara anya ụfọdụ ndị mmadụ nwere ndị ọzọ na-enweghị. A na-ewu ya site na mgbakọ ihe ndị a: mmekọrịta na-akwado onye, nkà imeli ihe bara uru, mmetụta ihe pụtara, na mgbe ụfọdụ, omume ịgbake site n''obere ọdachi tupu izute nke buru ibu.\n\nịtụrụ ntachi obi n''ụzọ a dị mkpa n''ihi na ọ pụtara na e nwere ike iwu ya. Imetụta mgbagwoju na ihe siri ike abụghị ihe akaebe na ị na-enweghị ntachi obi -- ọ nwere ike ịbụ usoro ntachi obi n''ezie na-egosi mgbe a na-ewu ya.'),
    ('00000000-0000-0000-0000-000000004101', 'fr', 'Ce Que Signifie Vraiment la Résilience', 'La résilience est souvent mal comprise comme « ne pas être affecté » par des choses difficiles, ou « rebondir » comme si rien ne s''était passé. Une image plus exacte est que la résilience est la capacité à être affecté par une expérience difficile tout en trouvant un moyen d''avancer -- elle inclut la lutte, pas son absence.\n\nLa résilience n''est pas non plus un trait de personnalité fixe que certains possèdent et d''autres non. Elle se construit à travers une combinaison de facteurs : des relations de soutien, des compétences pratiques d''adaptation, un sentiment de sens, et souvent, la pratique de se relever de petits revers avant d''en affronter de plus grands.\n\nPrésenter la résilience ainsi importe car cela signifie qu''elle peut se développer. Lutter avec quelque chose de difficile n''est pas une preuve que vous manquez de résilience -- c''est peut-être à cela que ressemble réellement le processus de résilience pendant qu''elle se construit.'),
    ('00000000-0000-0000-0000-000000004101', 'sw', 'Maana Halisi ya Uthabiti', 'Uthabiti mara nyingi hueleweka vibaya kama "kutoathirika" na mambo magumu, au "kurudi haraka" kana kwamba hakuna kilichotokea. Picha sahihi zaidi ni kwamba uthabiti ni uwezo wa kuathiriwa na uzoefu mgumu na bado kupata njia ya kusonga mbele -- unajumuisha mapambano, si kutokuwepo kwake.\n\nUthabiti pia si sifa ya kudumu ya kibinafsi ambayo baadhi ya watu wanayo na wengine hawana. Hujengwa kupitia mchanganyiko wa mambo: mahusiano ya kuunga mkono, ujuzi wa vitendo wa kukabiliana, hisia ya maana, na mara nyingi, mazoezi ya kupona kutoka vikwazo vidogo kabla ya kukabiliana na vikubwa.\n\nKuuweka uthabiti hivi kuna umuhimu kwa sababu kunamaanisha unaweza kujengwa. Kupambana na jambo gumu si uthibitisho kwamba hauna uthabiti -- inaweza kuwa mchakato ambao uthabiti unaonekana nao wakati unajengwa.'),
    ('00000000-0000-0000-0000-000000004101', 'ar', 'ما تعنيه المرونة حقًا', 'غالبًا ما يُساء فهم المرونة على أنها "عدم التأثر" بالأمور الصعبة، أو "الارتداد السريع" وكأن شيئًا لم يحدث. الصورة الأكثر دقة هي أن المرونة هي القدرة على التأثر بتجربة صعبة وما زلت تجد طريقًا للمضي قدمًا -- إنها تشمل الكفاح، وليس غيابه.\n\nالمرونة أيضًا ليست سمة شخصية ثابتة يمتلكها البعض ويفتقر إليها آخرون. إنها تُبنى من خلال مزيج من العوامل: العلاقات الداعمة، مهارات التأقلم العملية، الشعور بالمعنى، وغالبًا، ممارسة التعافي من النكسات الصغيرة قبل مواجهة الأكبر.\n\nتأطير المرونة بهذه الطريقة مهم لأنه يعني أنها يمكن تطويرها. الكفاح مع شيء صعب ليس دليلاً على افتقارك للمرونة -- قد يكون هذا هو شكل عملية المرونة الفعلي أثناء بنائها.'),

    ('00000000-0000-0000-0000-000000004102', 'pcm', 'Make You Clarify Your Values', 'Values na the qualities and priority wey matter well-well to how you want to live -- things like honesty, connection, growth, or independence. Dem different from goal: goal na something wey you go complete, but value na direction wey you go dey move towards am, e no go ever "finish" completely.\n\nAfter trauma, e common make you feel like say you no connect again to wetin you value, especially if survival don take priority for long time. To return to the question "wetin really matter to me" -- no be wetin suppose matter, or wetin matter to another person -- fit be grounding and clarifying exercise.\n\nOne simple approach na to notice moment wey feel meaningful or wey give you energy for the past, even small ones, and ask wetin value e reflect. As time dey go, dis one go build clearer picture to guide decision, especially when choice dey confuse you or when you no get direction.'),
    ('00000000-0000-0000-0000-000000004102', 'yo', 'Ṣíṣe Kedere Àwọn Ìlànà Rẹ', 'Àwọn ìlànà jẹ́ àwọn ànímọ́ àti ohun pàtàkì tí ó ṣe pàtàkì jùlọ sí bí o ṣe fẹ́ gbé ayé rẹ -- irú bí òtítọ́, ìsopọ̀, ìdàgbàsókè, tàbí òmìnira. Wọ́n yàtọ̀ sí àfojúsùn: àfojúsùn jẹ́ ohun tí o máa parí, nígbà tí ìlànà jẹ́ ìtọ́sọ́nà tí o máa ń bá a lọ síbẹ̀, tí kò ní parí pátápátá láé.\n\nLẹ́yìn ìpalára-ọkàn, ó wọ́pọ̀ láti nímọ̀lára bí ẹni pé o kò sopọ̀ mọ́ ohun tí o níye lórí, pàápàá tí ìwàláàyè bá ti jẹ́ pàtàkì jùlọ fún ìgbà pípẹ́. Ríbẹ̀wò sí ìbéèrè náà "kín ni ó ṣe pàtàkì fún mi ní ti gidi" -- kì í ṣe ohun tí ó yẹ kí ó ṣe pàtàkì, tàbí ohun tí ó ṣe pàtàkì fún ẹlòmíràn -- lè jẹ́ àṣàrò tí ó fìdí múlẹ̀ tí ó sì ṣe kedere.\n\nỌ̀nà kan tí ó rọrùn ni láti ṣàkíyèsí àwọn àkókò tí ó ní ìtumọ̀ tàbí tí ó fún ọ ní agbára ní ìgbà àtijọ́, kódà àwọn kéékèèké, kí o sì bi ìlànà wo ni wọ́n fi hàn. Ní àkókò, èyí máa ń kọ́ àwòrán tí ó ṣe kedere jù láti ṣamọ̀nà àwọn ìpinnu, pàápàá nígbà tí àṣàyàn kan bá dàrú tàbí tí kò ní ìtọ́sọ́nà.'),
    ('00000000-0000-0000-0000-000000004102', 'ha', 'Fayyace Dabi''unka', 'Dabi''u su ne halaye da fifikon da suka fi muhimmanci ga yadda kake son rayuwa -- abubuwa kamar gaskiya, hadin kai, ci gaba, ko yancin kai. Sun bambanta da manufa: manufa wani abu ne da za ka cimma, yayin da dabi''a ita ce hanyar da kake ci gaba da tafiya zuwa gare ta, ba ta taba "kammalawa" gaba daya ba.\n\nBayan rauni, abu ne na kowa a ji an rabu da abin da kake daraja, musamman idan tsira ta dauki fifiko na dogon lokaci. Komawa ga tambayar "me ke da muhimmanci a gare ni ainun" -- ba abin da ya kamata ya zama muhimmi ba, ko abin da ya kasance muhimmi ga wani -- na iya zama atisaye na gina tushe da fayyacewa.\n\nHanya daya mai sauki ita ce lura da lokutan da suka ji muhimmanci ko ba da kuzari a baya, ko da kananan ne, da tambayar wace dabi''a suka nuna. Da tafiyar lokaci, wannan yana gina hoto mai tsabta don jagorantar yanke shawara, musamman idan zabi ya ji rudani ko rashin shiriya.'),
    ('00000000-0000-0000-0000-000000004102', 'ig', 'Ikwuwapụta Ụkpụrụ Gị', 'Ụkpụrụ bụ àgwà na ihe mbụrụ anya kacha dị mkpa n''otú ị chọrọ ibi ndụ -- ihe ndị dị ka eziokwu, njikọ, uto, ma ọ bụ nnwere onwe. Ha dị iche na ebumnuche: ebumnuche bụ ihe ị ga-emezu, ebe ụkpụrụ bụ ntụzịaka ị ga-anọgide na-aga n''ihu, nke na-adịghị "zuru oke" kpamkpam.\n\nMgbe mmerụ ahụ-mmụọ gasịrị, ọ bụ ihe a na-ahụkarị inwe mmetụta ọpụpụ n''ozi na ihe ị ji kpọrọ ihe, karịsịa ma ọ bụrụ na ịdị ndụ ewereworị ụzọ ruo ogologo oge. ịlaghachi na ajụjụ ahụ "gịnị ka ọ bụ n''ezie mkpa nye m" -- ọ bụghị ihe kwesịrị ịdị mkpa, ma ọ bụ ihe dị mkpa nye onye ọzọ -- nwere ike ịbụ omume nchekwa na nkọwa.\n\nOtu ụzọ dị mfe bụ ịmata oge ndị dị uru ma ọ bụ nye ume n''oge gara aga, ọbụlagodi obere ndị, wee jụọ ụkpụrụ ole ha gosipụtara. Ka oge na-aga, nke a na-ewulite onyonyo doro anya iji duzie mkpebi, karịsịa mgbe nhọrọ dị ka ihe mgbagwoju anya ma ọ bụ enweghị ntụzịaka.'),
    ('00000000-0000-0000-0000-000000004102', 'fr', 'Clarifier Vos Valeurs', 'Les valeurs sont les qualités et priorités qui comptent le plus dans la façon dont vous voulez vivre -- des choses comme l''honnêteté, la connexion, la croissance, ou l''indépendance. Elles diffèrent des objectifs : un objectif est quelque chose que vous accomplissez, tandis qu''une valeur est une direction vers laquelle vous continuez d''avancer, jamais totalement « terminée ».\n\nAprès un traumatisme, il est courant de se sentir déconnecté de ce que l''on valorise, surtout si la survie a été prioritaire pendant longtemps. Revenir à la question « qu''est-ce qui compte vraiment pour moi » -- pas ce qui devrait compter, ni ce qui comptait pour quelqu''un d''autre -- peut être un exercice ancrant et clarifiant.\n\nUne approche simple consiste à remarquer les moments qui ont semblé porteurs de sens ou énergisants par le passé, même petits, et à se demander quelle valeur ils reflétaient. Avec le temps, cela construit une image plus claire pour guider les décisions, surtout lorsqu''un choix semble confus ou sans direction.'),
    ('00000000-0000-0000-0000-000000004102', 'sw', 'Kufafanua Maadili Yako', 'Maadili ni sifa na vipaumbele vinavyohusika zaidi na jinsi unavyotaka kuishi -- mambo kama uaminifu, muunganiko, ukuaji, au uhuru. Ni tofauti na malengo: lengo ni kitu unachokamilisha, ilhali thamani ni mwelekeo unaoendelea kuusogelea, haikamiliki kamwe kikamilifu.\n\nBaada ya kiwewe, ni kawaida kuhisi kutounganika na kile unachothamini, hasa kama kuishi kumekuwa kipaumbele kwa muda mrefu. Kurejea swali "ni nini hasa kina umuhimu kwangu" -- si kile kinachopaswa kuwa na umuhimu, au kile kilichokuwa na umuhimu kwa mtu mwingine -- kunaweza kuwa zoezi la kuleta msingi na ufafanuzi.\n\nMbinu moja rahisi ni kutambua nyakati zilizohisi na maana au kuleta nguvu zamani, hata ndogo, na kuuliza zinaakisi thamani gani. Baada ya muda, hili hujenga picha wazi zaidi ya kuongoza maamuzi, hasa wakati chaguo linapohisi kutatanisha au bila mwelekeo.'),
    ('00000000-0000-0000-0000-000000004102', 'ar', 'توضيح قيمك', 'القيم هي الصفات والأولويات الأكثر أهمية لكيفية رغبتك في العيش -- أشياء مثل الصدق، والتواصل، والنمو، أو الاستقلالية. تختلف عن الأهداف: الهدف شيء تكمله، بينما القيمة اتجاه تستمر في التحرك نحوه، ولا يكتمل أبدًا بشكل كامل.\n\nبعد الصدمة، من الشائع الشعور بالانفصال عما تقدّره، خاصة إذا كان البقاء على قيد الحياة أولوية لفترة طويلة. العودة إلى سؤال "ما الذي يهمني حقًا" -- وليس ما ينبغي أن يهم، أو ما كان يهم شخصًا آخر -- يمكن أن يكون تمرينًا للتأريض والتوضيح.\n\nأحد الأساليب البسيطة هو ملاحظة اللحظات التي شعرت بأنها ذات معنى أو محفزة في الماضي، حتى الصغيرة منها، والتساؤل عن القيمة التي تعكسها. بمرور الوقت، يبني هذا صورة أوضح لتوجيه القرارات، خاصة عندما يبدو الخيار محيرًا أو بلا اتجاه.'),

    ('00000000-0000-0000-0000-000000004103', 'pcm', 'How To Set Goal Wey Dey Trauma-Informed', 'To set goal after trauma dey work best when e take into account how recovery really dey happen: no be straight line, e get good days and setback, instead of steady progress wey dey go up always. Goals wey assume say improvement go dey constant often make people feel like say dem don fail when harder week show -- but dis one na normal part of the process, e no be sign say you dey go back.\n\nSmaller, process-focused goals ("I go try one grounding technique dis week") dey more sustainable pass big outcome-focused ones ("I no go ever feel anxious again"), because dem dey inside your direct control and dem dey give you something wey you fit actually act on.\n\nE also dey help to build flexibility inside am: you fit adjust goal without to abandon am. To return and reset goal na part of how you dey work with am, e no be sign say the goal -- or yourself -- don fail.'),
    ('00000000-0000-0000-0000-000000004103', 'yo', 'Ṣíṣètò Àfojúsùn Tí Ó Mọ̀ Nípa Ìpalára-Ọkàn', 'Ṣíṣètò àfojúsùn lẹ́yìn ìpalára-ọkàn máa ń ṣiṣẹ́ dáadáa jùlọ nígbà tí ó bá fi bí ìmúpadàbọ̀sípò gidi ṣe ń ṣẹlẹ̀ sí ọkàn: kì í ṣe ní ọ̀nà tààrà, pẹ̀lú ọjọ́ rere àti ìṣubú, dípò ìtẹ̀síwájú déédéé tí ó ń lọ sókè nígbà gbogbo. Àwọn àfojúsùn tí ó rò pé ìlọsíwájú máa ń jẹ́ déédéé sábà máa ń mú kí ènìyàn nímọ̀lára bí ẹni pé òun ti kùnà nígbà tí ọ̀sẹ̀ tí ó le bá dé -- èyí tí ó jẹ́ apá àjẹsára nínú ìlànà náà, kì í ṣe àmì ìpadàsẹ́yìn.\n\nÀwọn àfojúsùn kéékèèké tí ó dá lórí ìlànà ("Mo máa gbìyànjú ìlànà gírámdínì kan ní ọ̀sẹ̀ yìí") sábà máa ń lè fi ìdúró múlẹ̀ ju àwọn ńlá tí ó dá lórí àbájáde lọ ("Èmi kì yóò nímọ̀lára àníyàn mọ́"), nítorí wọ́n wà nínú agbára ìdarí rẹ tààrà, wọ́n sì fún ọ ní ohun tí o lè ṣe gan-an.\n\nÓ tún ran lọ́wọ́ láti kọ́ ìrọ̀lẹ́ sínú rẹ̀: a lè ṣe àtúnṣe àfojúsùn láì fi í sílẹ̀. Ríbẹ̀wò àti àtúntò àfojúsùn jẹ́ apá kan bí a ṣe ń bá a ṣiṣẹ́, kì í ṣe àmì pé àfojúsùn náà -- tàbí ìwọ fúnra rẹ -- kùnà.'),
    ('00000000-0000-0000-0000-000000004103', 'ha', 'Kayyade Manufa Da Ke Fahimtar Rauni', 'Kayyade manufa bayan rauni yana aiki mafi kyau idan ya lissafta yadda farfadowa take faruwa a zahiri: ba layi daya ba, tare da kyawawan kwanaki da koma-baya, maimakon ci gaba tsayayye koyaushe sama. Manufofin da ke dauka ci gaba zai kasance tabbatacce galibi suna sa mutane su ji sun gaza idan sun fuskanci mako mai wahala -- wanda shi ne sashi na dabi''a na tsarin, ba alamar komawa baya ba.\n\nKananan manufofi, wadanda suke mai da hankali kan tsari ("Zan gwada dabarar daidaitawa daya a wannan mako") sun fi dorewa fiye da manyan wadanda suke mai da hankali kan sakamako ("Ba zan taba jin damuwa ba"), domin suna karkashin ikonka kai tsaye kuma suna ba ka wani abu da za ka iya aikatawa.\n\nHaka kuma yana taimakawa a gina sassauci a cikinsa: ana iya daidaita manufa ba tare da yin watsi da ita ba. Komawa da sake saita manufa wani bangare ne na yadda ake aiki da ita, ba alamar cewa manufar -- ko kai -- kun gaza ba.'),
    ('00000000-0000-0000-0000-000000004103', 'ig', 'Ịtọ Ebumnuche Nke Na-Aghọta Mmerụ Ahụ-Mmụọ', 'Ịtọ ebumnuche mgbe mmerụ ahụ-mmụọ gasịrị na-arụ ọrụ nke ọma mgbe ọ gụnyere otú mgbake si apụta n''ezie: ọ bụghị n''usoro kwụ ọtọ, na ụbọchị ọma na ọdachi, karịa ọganihu nkwụsiri ike na-arịgokarị elu mgbe niile. Ebumnuche ndị na-eche na mmelite ga-anọgide na-eme ka ọtụtụ ndị mmadụ nwee mmetụta ka à ga-asị na ha dara mgbe izu siri ike bịara -- nke bụ akụkụ nkịtị nke usoro ahụ, ọ bụghị ihe ngosi mwada azụ.\n\nEbumnuche dị nta, nke lekwasịrị anya n''usoro ("Aga m anwale otu usoro nchekwa ahụ-mmụọ n''izu a") na-adịkarị ka ndị a pụrụ ịga n''ihu na ya karịa ndị buru ibu lekwasịrị anya na mmepụta ("Agaghị m enwekwa mmetụta ụjọ ọzọ"), n''ihi na ha dị n''ime njikwa gị kpọmkwem ma na-enye gị ihe ị ga-emebu n''ezie.\n\nỌ na-enyekwa aka iwulite ịdị n''ike mgbanwe n''ime ya: enwere ike ịgbanwe ebumnuche na-ahapụghị ya. ịlaghachi na iguzobegharị ebumnuche bụ akụkụ otú esi na ya na-arụ ọrụ, ọ bụghị ihe ngosi na ebumnuche ahụ -- ma ọ bụ gị onwe gị -- dara.'),
    ('00000000-0000-0000-0000-000000004103', 'fr', 'Définir des Objectifs Tenant Compte du Traumatisme', 'Fixer des objectifs après un traumatisme fonctionne mieux lorsque l''on tient compte de la façon dont le rétablissement se produit réellement : non linéaire, avec de bons jours et des revers, plutôt qu''une progression constante vers le haut. Les objectifs qui supposent une amélioration constante amènent souvent les gens à se sentir comme s''ils avaient échoué lorsqu''une semaine plus difficile survient -- ce qui est une partie normale du processus, pas un signe de régression.\n\nDes objectifs plus modestes, axés sur le processus (« j''essaierai une technique d''ancrage cette semaine ») ont tendance à être plus durables que de grands objectifs axés sur les résultats (« je ne me sentirai plus jamais anxieux »), car ils relèvent de votre contrôle direct et vous donnent quelque chose sur lequel agir concrètement.\n\nIl est également utile d''intégrer de la flexibilité : un objectif peut être ajusté sans être abandonné. Revisiter et réinitialiser un objectif fait partie du travail avec lui, et non un signe que l''objectif -- ou vous-même -- avez échoué.'),
    ('00000000-0000-0000-0000-000000004103', 'sw', 'Kuweka Malengo Yanayozingatia Kiwewe', 'Kuweka malengo baada ya kiwewe hufanya kazi vizuri zaidi yanapozingatia jinsi kupona kunavyotokea kihalisia: si kwa mstari ulionyooka, bali na siku nzuri na vikwazo, badala ya maendeleo thabiti yanayopanda juu daima. Malengo yanayodhania uboreshaji wa kudumu mara nyingi hufanya watu wahisi wameshindwa wakati wiki ngumu zaidi inapotokea -- jambo ambalo ni sehemu ya kawaida ya mchakato, si ishara ya kurudi nyuma.\n\nMalengo madogo, yanayolenga mchakato ("Nitajaribu mbinu moja ya kujiweka imara wiki hii") huwa endelevu zaidi kuliko makubwa yanayolenga matokeo ("Sitawahi tena kuhisi wasiwasi"), kwa sababu yako ndani ya udhibiti wako wa moja kwa moja na hukupa kitu cha kutenda kwa vitendo.\n\nHusaidia pia kujenga unyumbufu: lengo linaweza kurekebishwa bila kuachwa. Kurejea na kuweka upya lengo ni sehemu ya kulifanyia kazi, si ishara kwamba lengo -- au wewe -- limeshindwa.'),
    ('00000000-0000-0000-0000-000000004103', 'ar', 'وضع الأهداف المراعية للصدمة', 'يعمل وضع الأهداف بعد الصدمة بشكل أفضل عندما يأخذ في الاعتبار كيفية حدوث التعافي فعليًا: بشكل غير خطي، مع أيام جيدة ونكسات، بدلاً من تقدم ثابت متصاعد. الأهداف التي تفترض تحسنًا مستمرًا غالبًا ما تجعل الناس يشعرون وكأنهم فشلوا عند حدوث أسبوع أصعب -- وهو جزء طبيعي من العملية، وليس علامة على التراجع.\n\nالأهداف الأصغر التي تركز على العملية ("سأجرب تقنية تأريض واحدة هذا الأسبوع") تميل إلى أن تكون أكثر استدامة من الأهداف الكبيرة التي تركز على النتائج ("لن أشعر بالقلق بعد الآن")، لأنها ضمن سيطرتك المباشرة وتمنحك شيئًا يمكنك التصرف بشأنه فعليًا.\n\nيساعد أيضًا بناء المرونة: يمكن تعديل الهدف دون التخلي عنه. إعادة النظر في الهدف وإعادة ضبطه جزء من العمل عليه، وليس علامة على فشل الهدف -- أو فشلك.');

INSERT INTO quiz_question_translations (question_id, locale, text) VALUES
    ('00000000-0000-0000-0000-000000004301', 'pcm', 'According to dis lesson, wetin resilience dey include?'),
    ('00000000-0000-0000-0000-000000004301', 'yo', 'Gẹ́gẹ́ bí ẹ̀kọ́ yìí, kí ni ìfaradà ní nínú?'),
    ('00000000-0000-0000-0000-000000004301', 'ha', 'Bisa ga wannan darasi, me juriya take hadawa?'),
    ('00000000-0000-0000-0000-000000004301', 'ig', 'Dịka nkuzi a kwuru, gịnị ka ntachi obi gụnyere?'),
    ('00000000-0000-0000-0000-000000004301', 'fr', 'Selon cette leçon, qu''inclut la résilience ?'),
    ('00000000-0000-0000-0000-000000004301', 'sw', 'Kulingana na somo hili, uthabiti unajumuisha nini?'),
    ('00000000-0000-0000-0000-000000004301', 'ar', 'وفقًا لهذا الدرس، ماذا تشمل المرونة؟'),

    ('00000000-0000-0000-0000-000000004302', 'pcm', 'How dis lesson take describe the difference between value and goal?'),
    ('00000000-0000-0000-0000-000000004302', 'yo', 'Báwo ni ẹ̀kọ́ yìí ṣe ṣàpèjúwe ìyàtọ̀ láàrin ìlànà àti àfojúsùn?'),
    ('00000000-0000-0000-0000-000000004302', 'ha', 'Ta yaya wannan darasi ya bayyana bambanci tsakanin dabi''a da manufa?'),
    ('00000000-0000-0000-0000-000000004302', 'ig', 'Olee otú nkuzi a si kọwaa ọdịiche dị n''etiti ụkpụrụ na ebumnuche?'),
    ('00000000-0000-0000-0000-000000004302', 'fr', 'Comment cette leçon décrit-elle la différence entre une valeur et un objectif ?'),
    ('00000000-0000-0000-0000-000000004302', 'sw', 'Somo hili linaelezaje tofauti kati ya thamani na lengo?'),
    ('00000000-0000-0000-0000-000000004302', 'ar', 'كيف يصف هذا الدرس الفرق بين القيمة والهدف؟'),

    ('00000000-0000-0000-0000-000000004303', 'pcm', 'Why dis lesson recommend process-focused goals pass outcome-focused ones?'),
    ('00000000-0000-0000-0000-000000004303', 'yo', 'Kí nìdí tí ẹ̀kọ́ yìí fi dámọ̀ràn àfojúsùn tí ó dá lórí ìlànà ju èyí tí ó dá lórí àbájáde lọ?'),
    ('00000000-0000-0000-0000-000000004303', 'ha', 'Me ya sa wannan darasi ke ba da shawarar manufofin da suka mai da hankali kan tsari maimakon na sakamako?'),
    ('00000000-0000-0000-0000-000000004303', 'ig', 'Gịnị mere nkuzi a ji akwado ebumnuche lekwasịrị anya n''usoro karịa nke lekwasịrị anya na mmepụta?'),
    ('00000000-0000-0000-0000-000000004303', 'fr', 'Pourquoi cette leçon recommande-t-elle des objectifs axés sur le processus plutôt que sur les résultats ?'),
    ('00000000-0000-0000-0000-000000004303', 'sw', 'Kwa nini somo hili linapendekeza malengo yanayolenga mchakato kuliko yanayolenga matokeo?'),
    ('00000000-0000-0000-0000-000000004303', 'ar', 'لماذا يوصي هذا الدرس بالأهداف التي تركز على العملية بدلاً من النتائج؟');

INSERT INTO quiz_option_translations (option_id, locale, text) VALUES
    ('00000000-0000-0000-0000-000000004401', 'pcm', 'To no dey affected by hard things at all'),
    ('00000000-0000-0000-0000-000000004401', 'yo', 'Láti má nímọ̀lára ipa látinú ohun tó le rárá'),
    ('00000000-0000-0000-0000-000000004401', 'ha', 'Rashin fama da abubuwa masu wuya gaba daya'),
    ('00000000-0000-0000-0000-000000004401', 'ig', 'Enweghị mmetụta ihe ndị siri ike ma ọlị'),
    ('00000000-0000-0000-0000-000000004401', 'fr', 'Ne pas du tout être affecté par les choses difficiles'),
    ('00000000-0000-0000-0000-000000004401', 'sw', 'Kutokuathiriwa kabisa na mambo magumu'),
    ('00000000-0000-0000-0000-000000004401', 'ar', 'عدم التأثر إطلاقًا بالأمور الصعبة'),

    ('00000000-0000-0000-0000-000000004402', 'pcm', 'The struggle itself, no be say e no dey'),
    ('00000000-0000-0000-0000-000000004402', 'yo', 'Ìjàkadì fúnra rẹ̀, kì í ṣe àìsí rẹ̀'),
    ('00000000-0000-0000-0000-000000004402', 'ha', 'Kokawar kanta, ba rashinta ba'),
    ('00000000-0000-0000-0000-000000004402', 'ig', 'Mgbagwoju ahụ n''onwe ya, ọ bụghị enweghị ya'),
    ('00000000-0000-0000-0000-000000004402', 'fr', 'La lutte elle-même, pas son absence'),
    ('00000000-0000-0000-0000-000000004402', 'sw', 'Mapambano yenyewe, si kutokuwepo kwake'),
    ('00000000-0000-0000-0000-000000004402', 'ar', 'الكفاح نفسه، وليس غيابه'),

    ('00000000-0000-0000-0000-000000004403', 'pcm', 'Fixed character wey you either get or you no get'),
    ('00000000-0000-0000-0000-000000004403', 'yo', 'Ànímọ́ àìyípadà tí o yálà ní tàbí tí o kò ní'),
    ('00000000-0000-0000-0000-000000004403', 'ha', 'Hali tsayayye da ko dai kana da shi ko ba ka da shi'),
    ('00000000-0000-0000-0000-000000004403', 'ig', 'Àgwà a kapịrị ọnụ nke ị nwere ma ọ bụ na-enweghị'),
    ('00000000-0000-0000-0000-000000004403', 'fr', 'Un trait fixe que l''on possède ou non'),
    ('00000000-0000-0000-0000-000000004403', 'sw', 'Sifa ya kudumu ambayo ima unayo au huna'),
    ('00000000-0000-0000-0000-000000004403', 'ar', 'سمة ثابتة إما أن تمتلكها أو لا'),

    ('00000000-0000-0000-0000-000000004404', 'pcm', 'To avoid hard situation completely'),
    ('00000000-0000-0000-0000-000000004404', 'yo', 'Láti yẹra fún ipò tó le pátápátá'),
    ('00000000-0000-0000-0000-000000004404', 'ha', 'Guje wa yanayi masu wuya gaba daya'),
    ('00000000-0000-0000-0000-000000004404', 'ig', 'Izere ọnọdụ siri ike kpamkpam'),
    ('00000000-0000-0000-0000-000000004404', 'fr', 'Éviter complètement les situations difficiles'),
    ('00000000-0000-0000-0000-000000004404', 'sw', 'Kuepuka kabisa hali ngumu'),
    ('00000000-0000-0000-0000-000000004404', 'ar', 'تجنب المواقف الصعبة تمامًا'),

    ('00000000-0000-0000-0000-000000004411', 'pcm', 'Goal na direction you dey move towards forever; value na something you go complete'),
    ('00000000-0000-0000-0000-000000004411', 'yo', 'Àfojúsùn jẹ́ ìtọ́sọ́nà tí a ń bá a lọ síbẹ̀ láé; ìlànà jẹ́ ohun tí a máa parí'),
    ('00000000-0000-0000-0000-000000004411', 'ha', 'Manufa hanya ce ake ci gaba da zuwa gare ta har abada; dabi''a wani abu ne da za a cimma'),
    ('00000000-0000-0000-0000-000000004411', 'ig', 'Ebumnuche bụ ntụzịaka a na-anọgide na-aga n''ihu ruo mgbe ebighị ebi; ụkpụrụ bụ ihe a ga-emezu'),
    ('00000000-0000-0000-0000-000000004411', 'fr', 'Un objectif est une direction suivie indéfiniment ; une valeur est quelque chose que l''on accomplit'),
    ('00000000-0000-0000-0000-000000004411', 'sw', 'Lengo ni mwelekeo unaoendelea kuusogelea milele; thamani ni kitu unachokamilisha'),
    ('00000000-0000-0000-0000-000000004411', 'ar', 'الهدف اتجاه تستمر في التحرك نحوه إلى الأبد؛ القيمة شيء تكمله'),

    ('00000000-0000-0000-0000-000000004412', 'pcm', 'Value na direction you go dey move towards; goal na something you go complete'),
    ('00000000-0000-0000-0000-000000004412', 'yo', 'Ìlànà jẹ́ ìtọ́sọ́nà tí a ń bá a lọ síbẹ̀; àfojúsùn jẹ́ ohun tí a máa parí'),
    ('00000000-0000-0000-0000-000000004412', 'ha', 'Dabi''a hanya ce ake ci gaba da zuwa gare ta; manufa wani abu ne da za a cimma'),
    ('00000000-0000-0000-0000-000000004412', 'ig', 'Ụkpụrụ bụ ntụzịaka ị na-anọgide na-aga n''ihu; ebumnuche bụ ihe ị ga-emezu'),
    ('00000000-0000-0000-0000-000000004412', 'fr', 'Une valeur est une direction vers laquelle on continue d''avancer ; un objectif est quelque chose que l''on accomplit'),
    ('00000000-0000-0000-0000-000000004412', 'sw', 'Thamani ni mwelekeo unaoendelea kuusogelea; lengo ni kitu unachokamilisha'),
    ('00000000-0000-0000-0000-000000004412', 'ar', 'القيمة اتجاه تستمر في التحرك نحوه؛ الهدف شيء تكمله'),

    ('00000000-0000-0000-0000-000000004413', 'pcm', 'Dem both mean the exact same thing'),
    ('00000000-0000-0000-0000-000000004413', 'yo', 'Àwọn méjèèjì túmọ̀ sí ohun kan náà gan-an'),
    ('00000000-0000-0000-0000-000000004413', 'ha', 'Dukansu suna nufin abu daya ne daidai'),
    ('00000000-0000-0000-0000-000000004413', 'ig', 'Ha abụọ pụtara otu ihe ahụ kpọmkwem'),
    ('00000000-0000-0000-0000-000000004413', 'fr', 'Les deux signifient exactement la même chose'),
    ('00000000-0000-0000-0000-000000004413', 'sw', 'Zote mbili zinamaanisha kitu kilekile hasa'),
    ('00000000-0000-0000-0000-000000004413', 'ar', 'كلاهما يعني بالضبط نفس الشيء'),

    ('00000000-0000-0000-0000-000000004414', 'pcm', 'Value na only for career decisions'),
    ('00000000-0000-0000-0000-000000004414', 'yo', 'Ìlànà kàn ń ṣe pàtàkì fún ìpinnu iṣẹ́ nìkan'),
    ('00000000-0000-0000-0000-000000004414', 'ha', 'Dabi''u sun shafi shawarwarin sana''a ne kadai'),
    ('00000000-0000-0000-0000-000000004414', 'ig', 'Ụkpụrụ metụtara naanị mkpebi ọrụ'),
    ('00000000-0000-0000-0000-000000004414', 'fr', 'Les valeurs ne s''appliquent qu''aux décisions de carrière'),
    ('00000000-0000-0000-0000-000000004414', 'sw', 'Thamani zinahusu maamuzi ya kazi pekee'),
    ('00000000-0000-0000-0000-000000004414', 'ar', 'القيم تنطبق فقط على قرارات العمل'),

    ('00000000-0000-0000-0000-000000004421', 'pcm', 'Dem dey inside your direct control and dem dey give you something you fit act on'),
    ('00000000-0000-0000-0000-000000004421', 'yo', 'Wọ́n wà nínú agbára ìdarí rẹ tààrà, wọ́n sì fún ọ ní ohun tí o lè ṣe'),
    ('00000000-0000-0000-0000-000000004421', 'ha', 'Suna karkashin ikonka kai tsaye kuma suna ba ka wani abu da za ka iya aikatawa'),
    ('00000000-0000-0000-0000-000000004421', 'ig', 'Ha dị n''ime njikwa gị kpọmkwem ma na-enye gị ihe ị ga-emebu'),
    ('00000000-0000-0000-0000-000000004421', 'fr', 'Ils relèvent de votre contrôle direct et vous donnent quelque chose sur lequel agir'),
    ('00000000-0000-0000-0000-000000004421', 'sw', 'Yako ndani ya udhibiti wako wa moja kwa moja na hukupa kitu cha kutenda'),
    ('00000000-0000-0000-0000-000000004421', 'ar', 'ضمن سيطرتك المباشرة وتمنحك شيئًا تتصرف بشأنه'),

    ('00000000-0000-0000-0000-000000004422', 'pcm', 'Dem dey guarantee one particular outcome'),
    ('00000000-0000-0000-0000-000000004422', 'yo', 'Wọ́n ṣe ìdánilójú àbájáde kan pàtó'),
    ('00000000-0000-0000-0000-000000004422', 'ha', 'Suna tabbatar da wani takamaiman sakamako'),
    ('00000000-0000-0000-0000-000000004422', 'ig', 'Ha na-ekwe nkwa otu mmepụta akọwapụtara'),
    ('00000000-0000-0000-0000-000000004422', 'fr', 'Ils garantissent un résultat spécifique'),
    ('00000000-0000-0000-0000-000000004422', 'sw', 'Huhakikisha matokeo mahususi'),
    ('00000000-0000-0000-0000-000000004422', 'ar', 'تضمن نتيجة محددة'),

    ('00000000-0000-0000-0000-000000004423', 'pcm', 'Dem dey easier to brag about to people'),
    ('00000000-0000-0000-0000-000000004423', 'yo', 'Ó rọrùn láti fọ́nnu nípa rẹ̀ fún ẹlòmíràn'),
    ('00000000-0000-0000-0000-000000004423', 'ha', 'Sun fi saukin yin fahariya game da su ga wasu'),
    ('00000000-0000-0000-0000-000000004423', 'ig', 'Ọ dị mfe ikwupụta ha nye ndị ọzọ'),
    ('00000000-0000-0000-0000-000000004423', 'fr', 'Il est plus facile de s''en vanter auprès des autres'),
    ('00000000-0000-0000-0000-000000004423', 'sw', 'Ni rahisi zaidi kujisifu kwa wengine'),
    ('00000000-0000-0000-0000-000000004423', 'ar', 'من الأسهل التباهي بها أمام الآخرين'),

    ('00000000-0000-0000-0000-000000004424', 'pcm', 'Dem no need any flexibility once you set dem'),
    ('00000000-0000-0000-0000-000000004424', 'yo', 'Wọn kò nílò ìrọ̀lẹ́ kankan lẹ́yìn ìgbà tí a bá tò wọ́n'),
    ('00000000-0000-0000-0000-000000004424', 'ha', 'Ba sa bukatar sassauci da zarar an saita su'),
    ('00000000-0000-0000-0000-000000004424', 'ig', 'Ha achọghị ịdị n''ike mgbanwe ozugbo a tọrọ ha'),
    ('00000000-0000-0000-0000-000000004424', 'fr', 'Ils ne nécessitent aucune flexibilité une fois fixés'),
    ('00000000-0000-0000-0000-000000004424', 'sw', 'Hayahitaji unyumbufu wowote mara yanapowekwa'),
    ('00000000-0000-0000-0000-000000004424', 'ar', 'لا تتطلب أي مرونة بمجرد تحديدها');
